const F=require('./flora.js'),E=require('./ecology.js'),a=require('node:assert/strict');let tests=[];function test(n,f){f();tests.push(n)}function run(s,n){for(let i=0;i<n;i++){F.tick(s);for(let e of Object.values(s.last))a.ok(Math.abs(e)<1e-6,`${i} ${JSON.stringify(s.last)}`)}return s}
test('seis espécies e habitats compatíveis',()=>{let s=F.create();a.equal(F.metrics(s).richness,6);for(let c of s.cells)if(c.sp>=0)a.ok(F.species[c.sp].hab.includes(c.kind))});
test('determinismo e restauração JSON',()=>{let s=run(F.create(),80),t=JSON.parse(JSON.stringify(s));a.deepEqual(run(s,80),run(t,80))});
test('um ano: conservação e estados não negativos em três climas',()=>{for(let w of ['auto','drought','storm']){let s=F.create();s.weather=w;run(s,1460);for(let c of s.cells){for(let k of ['b','res','pn','n','litter','ln','fruit','fruitN'])a.ok(Number.isFinite(c[k])&&c[k]>=-1e-10);a.ok(c.bank.every(v=>v>=0&&Number.isFinite(v)))}}});
test('sem polinizadores: sem frutos sexuais, esporos continuam',()=>{let s=F.create();s.pollinators='none';run(s,600);a.equal(s.floraEvents.pollinated,0);a.ok(s.floraEvents.propagules>0);a.ok(s.cells.every(c=>c.phase!=='fruto'))});
test('sem mariposa: orquídea não frutifica',()=>{let s=F.create();s.pollinators='noMoth';for(let i=0;i<1000;i++){F.tick(s);a.ok(s.cells.every(c=>c.sp!==3||c.phase!=='fruto'))}a.ok(s.floraEvents.pollinated>0)});
test('corte conserva C e N e permite regeneração',()=>{let s=F.create(),i=s.cells.findIndex(c=>c.sp===1),before=F.totals(s);F.edit(s,i,'cut');let after=F.totals(s);a.ok(Math.abs(before.c-after.c)<1e-8&&Math.abs(before.n-after.n)<1e-8);a.equal(s.cells[i].sp,-1);run(s,120);a.ok(s.floraEvents.germinations>0)});
test('sem banco de sementes e sem vizinhos: não nasce espontaneamente',()=>{let s=F.create();for(let i=0;i<s.cells.length;i++){F.edit(s,i,'cut');s.cells[i].bank.fill(0)}run(s,120);a.equal(F.metrics(s).richness,0)});
test('introdução de propágulos contabilizada e restrita ao habitat',()=>{let s=F.create(),b=F.totals(s);a.equal(F.edit(s,0,'seed:0'),false);a.ok(F.edit(s,0,'seed:4'));let z=F.totals(s);a.ok(Math.abs(z.c-b.c-.024)<1e-8&&Math.abs(z.n-b.n-.00192)<1e-8)});
test('escuridão: zero fotossíntese e sem germinação',()=>{let s=F.create();F.edit(s,0,'cut');s.light='dark';run(s,100);a.equal(s.floraEvents.germinations,0);a.ok(s.cells.every(c=>c.photo===0))});
test('colheita exporta fruto e nutrientes',()=>{let s=F.create();let c=s.cells[0];c.phase='fruto';c.fruit=.016;c.fruitN=.00128;let b=F.totals(s);a.ok(F.edit(s,0,'harvest'));let z=F.totals(s);a.ok(Math.abs(b.c-z.c-.016)<1e-8&&Math.abs(b.n-z.n-.00128)<1e-8)});
let summaries={};for(let w of ['auto','drought','storm']){let s=F.create();s.weather=w;run(s,1460);summaries[w]={...F.metrics(s),events:s.floraEvents,water:E.metrics(s).water}}console.log(JSON.stringify({passed:tests.length,tests,summaries},null,2));
